use std::io::{self, Read};

fn input() -> Vec<String> {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    s.split_whitespace().map(|t| t.to_string()).collect()
}

/// A fixed set of buckets, with saturating counts. Everything the rest
/// of the program does to it goes through these methods.
struct Histogram {
    lo: i64,
    width: i64,
    buckets: Vec<u32>,
    below: u32,
    above: u32,
}

impl Histogram {
    fn new(lo: i64, width: i64, n: usize) -> Self {
        Histogram { lo, width, buckets: vec![0; n], below: 0, above: 0 }
    }

    /// Which bucket a value belongs in, or None if it is outside.
    fn bucket_of(&self, x: i64) -> Option<usize> {
        if x < self.lo {
            return None;
        }
        let i = ((x - self.lo) / self.width) as usize;
        if i < self.buckets.len() { Some(i) } else { None }
    }

    fn add(&mut self, x: i64) {
        match self.bucket_of(x) {
            Some(i) => self.buckets[i] = self.buckets[i].saturating_add(1),
            None if x < self.lo => self.below = self.below.saturating_add(1),
            None => self.above = self.above.saturating_add(1),
        }
    }

    fn total(&self) -> u32 {
        self.buckets.iter().sum::<u32>() + self.below + self.above
    }

    /// The index of the fullest bucket, ties going to the lowest index.
    fn mode(&self) -> Option<usize> {
        let mut best: Option<usize> = None;
        for (i, c) in self.buckets.iter().enumerate() {
            if *c > 0 && (best.is_none() || *c > self.buckets[best.unwrap()]) {
                best = Some(i);
            }
        }
        best
    }
}

fn main() {
    let t = input();
    if t.is_empty() {
        return;
    }
    let lo: i64 = t[0].parse().unwrap();
    let width: i64 = t[1].parse().unwrap();
    let n: usize = t[2].parse().unwrap();

    let mut h = Histogram::new(lo, width, n);
    for s in &t[3..] {
        h.add(s.parse().unwrap());
    }

    let shown: Vec<String> = h.buckets.iter().map(|c| c.to_string()).collect();
    println!("buckets {}", shown.join(" "));
    println!("outside {} {}", h.below, h.above);
    println!("total {}", h.total());
    match h.mode() {
        Some(i) => println!("mode {}", i),
        None => println!("mode none"),
    }
}
